// ═══ STEP 1: COLLECT THREAD DUMP ═══
// Command line:
// jstack <PID> > thread_dump.txt
// Or: kill -3 <PID> (dumps to stderr/log)
// Or programmatic:
ThreadMXBean tmx = ManagementFactory.getThreadMXBean();
ThreadInfo[] infos = tmx.dumpAllThreads(true, true);
for (ThreadInfo info : infos) {
    System.out.println(info.getThreadName() + ": " + info.getThreadState());
    if (info.getLockName() != null)
        System.out.println("  Blocked on: " + info.getLockName());
    if (info.getLockOwnerName() != null)
        System.out.println("  Lock held by: " + info.getLockOwnerName());
}

// ═══ STEP 2: ANALYZE THREAD STATES ═══
// Count threads by state:
Map<Thread.State, Long> stateCounts = Arrays.stream(infos)
    .collect(Collectors.groupingBy(ThreadInfo::getThreadState, Collectors.counting()));
// BLOCKED: 150 → lock contention!
// WAITING: 50 → pool workers idle or waiting for downstream
// TIMED_WAITING: 20 → sleeping/timeout
// RUNNABLE: 30 → actually working

// ═══ STEP 3: IDENTIFY THE BOTTLENECK ═══

// ROOT CAUSE 1: EXCESSIVE LOCKING (coarse/long hold)
// Thread dump: 150 threads BLOCKED on "com.bank.AccountService@0x7f..."
// Lock held by: "http-nio-exec-5" → stack shows AccountService.transfer()
// Lock hold time: 500ms (includes DB query INSIDE synchronized!)
// FIX: move DB query outside synchronized, or fine-grained lock!

// ROOT CAUSE 2: UNDERSIZED THREAD POOL
// Thread dump: all pool workers RUNNABLE (busy)
// Queue: 5000 tasks waiting!
// FIX: increase pool size OR optimize task duration!
// Check: pool.getActiveCount() == pool.getMaximumPoolSize() → pool saturated!

// ROOT CAUSE 3: SLOW DOWNSTREAM
// Thread dump: 100 threads TIMED_WAITING in SocketInputStream.read()
// → threads waiting for HTTP response from slow service!
// FIX: add timeouts, circuit breaker, cache responses!

// ROOT CAUSE 4: DB CONNECTION POOL CONTENTION
// Thread dump: 100 threads WAITING in HikariPool.getConnection()
// → all connections in use! Threads waiting for a free connection!
// FIX: increase HikariCP maximumPoolSize, optimize query duration, add caching!

// ═══ STEP 4: JFR + JDK MISSION CONTROL ═══
// Start recording:
// jcmd <PID> JFR.start duration=60s filename=contention.jfr
// Analyze in JDK Mission Control:
// → "Lock Instances" tab: which locks are most contended?
// → "Thread" tab: time spent BLOCKED per thread
// → "Hot Methods" tab: which methods hold locks longest?
