// ─── File: src/test/java/com/bank/contention/ContentionTroubleshootTest.java ───
package com.bank.contention;

import org.junit.jupiter.api.Test;
import java.lang.management.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.stream.*;
import static org.assertj.core.api.Assertions.*;

class ContentionTroubleshootTest {

    // ═══ Simulate contention: many threads blocked on one lock ═══
    @Test
    void simulateContention_analyzeThreadDump() throws InterruptedException {
        Object hotLock = new Object();
        int threads = 20;
        CountDownLatch allStarted = new CountDownLatch(threads);
        CountDownLatch canFinish = new CountDownLatch(1);

        // 1 holder: holds lock for 2 seconds
        Thread holder = new Thread(() -> {
            synchronized (hotLock) {
                allStarted.countDown();
                try { canFinish.await(10, TimeUnit.SECONDS); } catch (InterruptedException e) {}
            }
        }, "lock-holder");
        holder.start();

        // 19 waiters: blocked on same lock
        for (int i = 0; i < threads - 1; i++) {
            new Thread(() -> {
                allStarted.countDown();
                synchronized (hotLock) { /* wait for lock */ }
            }, "waiter-" + i).start();
        }

        allStarted.await();
        Thread.sleep(200);  // let waiters block

        // ═══ ANALYZE: thread dump! ═══
        ThreadMXBean tmx = ManagementFactory.getThreadMXBean();
        ThreadInfo[] infos = tmx.dumpAllThreads(true, true);

        Map<Thread.State, Long> states = Arrays.stream(infos)
            .collect(Collectors.groupingBy(ThreadInfo::getThreadState, Collectors.counting()));
        System.out.println("Thread states: " + states);

        long blocked = Arrays.stream(infos)
            .filter(i -> i.getThreadState() == Thread.State.BLOCKED)
            .count();
        System.out.println("BLOCKED threads: " + blocked);
        assertThat(blocked).isGreaterThanOrEqualTo(15);  // many blocked!

        // Find lock owner:
        Arrays.stream(infos)
            .filter(i -> i.getThreadState() == Thread.State.BLOCKED)
            .findFirst()
            .ifPresent(i -> {
                System.out.println("Blocked on: " + i.getLockName());
                System.out.println("Lock owner: " + i.getLockOwnerName());
                assertThat(i.getLockOwnerName()).isEqualTo("lock-holder");
            });

        canFinish.countDown();
        Thread.sleep(500);
    }

    // ═══ Pool saturation detection ═══
    @Test
    void detectPoolSaturation() throws InterruptedException {
        ThreadPoolExecutor pool = new ThreadPoolExecutor(
            2, 2, 0, TimeUnit.SECONDS, new LinkedBlockingQueue<>(100));

        for (int i = 0; i < 50; i++) {
            pool.submit(() -> { try { Thread.sleep(500); } catch (InterruptedException e) {} });
        }
        Thread.sleep(100);

        System.out.println("Active: " + pool.getActiveCount() + "/" + pool.getMaximumPoolSize());
        System.out.println("Queued: " + pool.getQueue().size());
        boolean saturated = pool.getActiveCount() == pool.getMaximumPoolSize()
            && pool.getQueue().size() > 0;
        System.out.println("Pool saturated: " + saturated);
        assertThat(saturated).isTrue();

        pool.shutdownNow();
    }

    // ═══ Deadlock detection ═══
    @Test
    void detectDeadlock() {
        ThreadMXBean tmx = ManagementFactory.getThreadMXBean();
        long[] deadlocked = tmx.findDeadlockedThreads();
        assertThat(deadlocked).isNull();  // no deadlock right now!
    }
}
